import json
import re
import subprocess
from pathlib import Path

root = Path.cwd()
target = "{{ git_target }}"
max_tests = int("{{ max_related_tests }}")

TEST_RE = re.compile(r'(src/test/|/test/|/tests/|cypress/|playwright/|\\.cy\\.ts$|\\.spec\\.[jt]sx?$|\\.test\\.[jt]sx?$|Test\\.java$|IT\\.java$)')
MOCK_MARKERS = [
    '@Mock', '@MockBean', '@Spy', '@SpyBean', 'mock(', 'when(',
    'doReturn(', 'verify(', 'jest.mock(', 'vi.mock(', 'cy.intercept('
]
REALISM_MARKERS = [
    '@SpringBootTest', '@WebMvcTest', '@DataJpaTest', '@JdbcTest', '@AutoConfigureMockMvc',
    'MockMvc', 'TestRestTemplate', 'WebTestClient', '@Transactional', 'Flyway',
    '@Sql', '@Container', 'Testcontainers', 'Playwright', 'cypress/', 'cy.visit(',
    'page.goto(', 'supertest(', 'fetch(', 'axios.'
]

CONTENT_HINTS = {
    'network': ['http://', 'https://', 'resttemplate', 'webclient', 'httpclient', '/api/v1/', 'httpget(', 'httppost(', 'httpput(', 'wiremock'],
    'database': ['datasource', 'jdbc', 'preparedstatement', 'resultset', '@query', 'select ', 'update ', 'insert ', 'delete ', 'sqlite', 'flyway'],
    'docker': ['docker', 'processbuilder', 'dockercontainermanager'],
    'json': ['objectmapper', 'jsonnode', 'serializer', 'deserializer', 'json'],
    'security': ['apikey', 'x-forwarded-for', 'filterchain', 'onceperrequestfilter', 'authentication', 'authorization'],
    'concurrency': ['synchronized', 'atomicinteger', 'countdownlatch', 'executorservice', 'thread.sleep', 'concurrent']
}


def run(cmd):
    result = subprocess.run(cmd, cwd=root, text=True, capture_output=True, check=False)
    return result.stdout


def read_text(rel_path):
    try:
        return (root / rel_path).read_text(encoding='utf-8', errors='ignore')
    except Exception:
        return ''


def list_all_files():
    tracked = run(['git', 'ls-files']).splitlines()
    if tracked:
        return tracked
    result = []
    for path in root.rglob('*'):
        if path.is_file() and '.git/' not in str(path):
            result.append(path.relative_to(root).as_posix())
    return result


def changed_files():
    if target == 'WORKTREE':
        out = run(['git', 'diff', '--name-only', 'HEAD'])
    else:
        out = run(['git', 'diff', '--name-only', target])
    return [line.strip() for line in out.splitlines() if line.strip()]


def classify(path):
    lowered = path.lower()
    if '/controller/' in lowered or '/api/' in lowered or '/rest/' in lowered or 'webhook' in lowered:
        return 'api-boundary'
    if '/repository/' in lowered or '/dao/' in lowered or 'db/migration' in lowered or lowered.endswith('.sql'):
        return 'database'
    if '/security/' in lowered or '/auth/' in lowered or 'permission' in lowered:
        return 'security'
    if 'scheduler' in lowered or 'schedule' in lowered or 'async' in lowered or 'queue' in lowered:
        return 'async-runtime'
    if '/service/' in lowered:
        return 'service'
    if '/dto/' in lowered or '/mapper/' in lowered or 'serializer' in lowered or 'deserializer' in lowered:
        return 'serialization'
    if '/components/' in lowered or '/pages/' in lowered or '/hooks/' in lowered or lowered.endswith('.tsx') or lowered.endswith('.jsx'):
        return 'frontend-ui'
    if '/config/' in lowered or lowered.endswith('.yml') or lowered.endswith('.yaml') or lowered.endswith('.properties'):
        return 'configuration'
    return 'other'


def extract_hints(content):
    lowered = content.lower()
    hits = []
    for name, markers in CONTENT_HINTS.items():
        if any(marker in lowered for marker in markers):
            hits.append(name)
    return sorted(hits)


def service_subkind(kind, hints):
    if kind != 'service':
        return None
    if 'docker' in hints:
        return 'container-orchestration'
    if 'network' in hints:
        return 'network-orchestration'
    if 'database' in hints:
        return 'db-touchpoint'
    if 'json' in hints:
        return 'serialization-touchpoint'
    return 'internal-service'


def boundary_class(kind, subkind):
    if kind in {'security', 'api-boundary', 'database', 'async-runtime', 'serialization', 'frontend-ui', 'configuration'}:
        return 'system-boundary'
    if subkind in {'container-orchestration', 'network-orchestration', 'db-touchpoint', 'serialization-touchpoint'}:
        return 'service-with-external-boundary'
    if kind == 'service':
        return 'service-internal-or-mixed'
    return 'internal'


def recommended_test_type(kind, subkind):
    if kind == 'security':
        return 'webmvc-slice'
    if kind == 'api-boundary':
        return 'webmvc-or-api-integration'
    if kind == 'database':
        return 'datajpa-or-jdbc-slice'
    if kind == 'async-runtime':
        return 'integration'
    if kind == 'serialization':
        return 'api-or-serialization-integration'
    if kind == 'frontend-ui':
        return 'component-or-e2e-if-cross-layer'
    if kind == 'configuration':
        return 'spring-integration'
    if subkind in {'container-orchestration', 'network-orchestration', 'db-touchpoint', 'serialization-touchpoint'}:
        return 'integration-or-slice'
    return 'unit-or-spring-integration'


def priority_hint(style, boundary, kind):
    if style == 'none-detected' and boundary in {'system-boundary', 'service-with-external-boundary'}:
        return 'P0'
    if style == 'mock-heavy' and kind == 'security':
        return 'P0'
    if style == 'mock-heavy' and boundary in {'system-boundary', 'service-with-external-boundary'}:
        return 'P1'
    if style == 'mixed' and boundary in {'system-boundary', 'service-with-external-boundary'}:
        return 'P2'
    return 'P3'


def link_strength(prod_stem, candidates):
    if not candidates:
        return 'none'
    exact_name = prod_stem + 'test'
    exact_it = prod_stem + 'it'
    bases = [Path(item).stem.lower() for item in candidates]
    if exact_name in bases or exact_it in bases:
        return 'exact-name'
    return 'fuzzy-name'


all_files = list_all_files()
changed = changed_files()
prod_changed = [p for p in changed if not TEST_RE.search(p) and 'node_modules/' not in p]
test_changed = [p for p in changed if TEST_RE.search(p)]
findings = []

for prod in prod_changed:
    prod_stem = Path(prod).stem.lower()
    prod_kind = classify(prod)
    prod_content = read_text(prod)
    hints = extract_hints(prod_content)
    subkind = service_subkind(prod_kind, hints)
    candidates = []
    for file_path in all_files:
        if not TEST_RE.search(file_path):
            continue
        base = Path(file_path).stem.lower()
        if prod_stem in base or base in prod_stem:
            candidates.append(file_path)
    candidates = candidates[:max_tests]
    mock_count = 0
    real_count = 0
    related_tests = []
    for test_file in candidates:
        content = read_text(test_file)
        lowered_content = content.lower()
        mock_hits = sum(lowered_content.count(marker.lower()) for marker in MOCK_MARKERS)
        realism_hits = sum(lowered_content.count(marker.lower()) for marker in REALISM_MARKERS)
        mock_count += mock_hits
        real_count += realism_hits
        related_tests.append({
            'path': test_file,
            'mock_hits': mock_hits,
            'realism_hits': realism_hits
        })
    if mock_count > 0 and real_count == 0:
        style = 'mock-heavy'
    elif real_count > 0 and mock_count == 0:
        style = 'realistic-only'
    elif real_count > 0 and mock_count > 0:
        style = 'mixed'
    else:
        style = 'none-detected' if not related_tests else 'unknown-lightweight'
    boundary = boundary_class(prod_kind, subkind)
    findings.append({
        'path': prod,
        'kind': prod_kind,
        'subkind': subkind,
        'boundary_class': boundary,
        'content_hints': hints,
        'related_tests': related_tests,
        'test_link_strength': link_strength(prod_stem, candidates),
        'test_style': style,
        'mock_signal_count': mock_count,
        'realism_signal_count': real_count,
        'recommended_minimum_test_type': recommended_test_type(prod_kind, subkind),
        'priority_hint': priority_hint(style, boundary, prod_kind)
    })

summary = {
    'git_target': target,
    'changed_files_total': len(changed),
    'prod_files_changed': len(prod_changed),
    'test_files_changed': len(test_changed),
    'mock_heavy_findings': sum(1 for item in findings if item['test_style'] == 'mock-heavy'),
    'boundary_findings': sum(1 for item in findings if item['boundary_class'] in {'system-boundary', 'service-with-external-boundary'}),
    'findings_with_realism': sum(1 for item in findings if item['realism_signal_count'] > 0)
}

audit = {
    'scope': summary,
    'changed_production_files': prod_changed,
    'changed_test_files': test_changed,
    'findings': findings,
    'notes': [
        'mock_signal_count is only a heuristic and not a severity score',
        'test linkage is name-based and should be treated as suggestive, not definitive',
        'service findings with network/docker/database/json hints are more likely to hide real integration gaps'
    ]
}

print(json.dumps(audit, indent=2))
